import time, threading

class RateLimiter:
    def __init__(self, per_sec):
        self.interval = 1.0 / per_sec
        self.lock = threading.Lock()
        self.next = 0.0
    def __call__(self):
        with self.lock:
            now = time.monotonic()
            wait = self.next - now
            if wait > 0: time.sleep(wait)
            self.next = max(now, self.next) + self.interval

